/* Northwake: pre-dawn night, one first-light accent. Tokens and decisions in DESIGN.md. */
:root {
  --bg: oklch(0.19 0.035 262);
  --surface: oklch(0.235 0.04 262);
  --ink: oklch(0.95 0.012 85);
  --muted: oklch(0.8 0.025 255);
  --accent: oklch(0.83 0.11 68);
  --line: oklch(0.62 0.07 255);
  --glow: oklch(0.42 0.07 50);
  --nav-bg: oklch(0.19 0.035 262 / 0.8);

  --display: "Young Serif", Georgia, serif;
  --body: "Figtree", system-ui, sans-serif;

  --nav-h: 4.5rem;
  --gutter: clamp(1.25rem, 4vw, 3rem);
  --ease: cubic-bezier(0.22, 1, 0.36, 1); /* ease-out quint */

  --z-sticky: 10;
  --z-skip: 20;
}

*, *::before, *::after { box-sizing: border-box; }

html {
  scroll-behavior: smooth;
  scroll-padding-top: calc(var(--nav-h) + 1rem);
  background: var(--bg);
  color: var(--ink);
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font: 400 1.0625rem/1.65 var(--body);
  letter-spacing: 0.005em;
  caret-color: var(--accent);
}

::selection { background: var(--accent); color: var(--bg); }

h1, h2 {
  font-family: var(--display);
  font-weight: 400;
  text-wrap: balance;
  margin: 0;
}

a { color: inherit; text-underline-offset: 0.2em; }

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 0.25rem;
}

.skip {
  position: absolute;
  left: 1rem;
  top: -4rem;
  z-index: var(--z-skip);
  padding: 0.75rem 1rem;
  background: var(--accent);
  color: var(--bg);
  font-weight: 600;
  border-radius: 0.5rem;
}
.skip:focus { top: 1rem; }

/* ---------- Nav: frosted, sticky ---------- */
.nav {
  position: sticky;
  top: 0;
  z-index: var(--z-sticky);
  height: var(--nav-h);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding-inline: var(--gutter);
  background: var(--nav-bg);
  -webkit-backdrop-filter: blur(16px) saturate(140%);
  backdrop-filter: blur(16px) saturate(140%);
  border-bottom: 1px solid oklch(0.95 0.012 85 / 0.08);
}
.nav nav { display: flex; align-items: center; gap: clamp(0.75rem, 3vw, 2rem); }
.nav nav > a:not(.button) {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  font-weight: 500;
  text-decoration: none;
}

.wordmark {
  font-family: var(--display);
  font-size: 1.375rem;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
}

@supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
  .nav { background: var(--bg); }
}
@media (prefers-reduced-transparency: reduce), (prefers-contrast: more) {
  .nav { background: var(--bg); backdrop-filter: none; -webkit-backdrop-filter: none; }
}
@media (prefers-contrast: more) {
  .nav { border-bottom-color: var(--muted); }
}

/* ---------- Buttons & links ---------- */
.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 3.25rem;
  padding: 0.75rem 1.5rem;
  border: 1px solid transparent; /* visible edge in forced-colors */
  border-radius: 999px;
  background: var(--accent);
  color: var(--bg);
  font-weight: 600;
  text-decoration: none;
  touch-action: manipulation;
  transition: background-color 200ms var(--ease), transform 90ms var(--ease);
}
.button--small { min-height: 2.75rem; padding: 0.5rem 1.125rem; font-size: 0.9375rem; }
.button:active { transform: scale(0.97); background: oklch(0.76 0.11 68); }

.textlink {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  font-weight: 500;
  text-decoration-color: var(--line);
  text-decoration-thickness: 1px;
  transition: text-decoration-color 200ms var(--ease);
}

@media (hover: hover) {
  .button:hover { background: oklch(0.88 0.1 72); }
  .textlink:hover,
  .nav nav > a:not(.button):hover { text-decoration: underline; text-decoration-color: var(--accent); }
}

/* ---------- Hero ---------- */
.hero {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  min-height: calc(100dvh - var(--nav-h));
  display: grid;
  align-items: center;
  gap: 3rem;
  padding: clamp(4rem, 10vh, 7rem) var(--gutter) clamp(8rem, 18vh, 11rem);
}

/* ambient: the first light, low on the horizon, sitting behind the night's line */
.hero::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(120% 55% at 70% 108%, var(--glow), transparent 70%),
    linear-gradient(to bottom, var(--bg) 40%, oklch(0.22 0.045 265));
}

.hero__copy { max-width: 38rem; }

.hero h1 {
  font-size: clamp(2.625rem, 5.5vw + 1rem, 5.5rem);
  line-height: 1.02;
  letter-spacing: -0.02em;
}

.lede {
  margin: 1.75rem 0 2.5rem;
  max-width: 34rem;
  font-size: clamp(1.0625rem, 0.5vw + 0.95rem, 1.25rem);
  line-height: 1.6;
  color: var(--muted);
  text-wrap: pretty;
}

.hero__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem 1.75rem;
}

/* the ring, seen slightly from above */
.ring {
  justify-self: center;
  width: min(70vw, 22rem);
  aspect-ratio: 1;
  border-radius: 50%;
  background: conic-gradient(from 200deg,
    oklch(0.55 0.02 255), oklch(0.85 0.015 255) 12%, oklch(0.4 0.03 260) 30%,
    oklch(0.7 0.02 255) 48%, oklch(0.9 0.06 70) 58%, oklch(0.45 0.03 260) 72%,
    oklch(0.78 0.02 255) 88%, oklch(0.55 0.02 255));
  -webkit-mask: radial-gradient(closest-side, transparent 78%, #000 79.5%, #000 98.5%, transparent);
  mask: radial-gradient(closest-side, transparent 78%, #000 79.5%, #000 98.5%, transparent);
  transform: perspective(60rem) rotateX(64deg) rotateZ(-8deg);
  filter: drop-shadow(0 1.5rem 2rem oklch(0.1 0.03 262 / 0.6));
}

@media (min-width: 56rem) {
  .hero { grid-template-columns: 1.3fr 1fr; }
}

/* ---------- Signature: the hypnogram step-line ---------- */
.hypno { display: block; overflow: visible; }
.hypno path {
  fill: none;
  stroke: var(--line);
  stroke-width: 2;
  stroke-linejoin: round;
  stroke-linecap: round;
  vector-effect: non-scaling-stroke;
}

.hypno--horizon {
  position: absolute;
  inset: auto 0 clamp(1.5rem, 5vh, 3rem) 0;
  width: 100%;
  height: clamp(4rem, 12vh, 6.5rem);
  z-index: -1;
  animation: draw 2.4s var(--ease) 0.2s backwards;
}
/* the final step up is the waking moment: it gets the first light */
.hypno--horizon path,
.hypno--wake path { stroke: url(#none) var(--line); }

@keyframes draw {
  from { clip-path: inset(0 100% 0 0); }
}

/* ---------- Reviews ---------- */
.reviews {
  background: var(--surface);
  padding: clamp(5rem, 12vw, 8rem) var(--gutter) clamp(4rem, 10vw, 6rem);
}

.reviews h2 {
  font-size: clamp(2rem, 3vw + 1rem, 3.25rem);
  line-height: 1.1;
  letter-spacing: -0.01em;
  margin-bottom: clamp(2.5rem, 5vw, 4rem);
}

.reviews__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 17rem), 1fr));
  gap: 3rem clamp(2rem, 4vw, 4rem);
}

.reviews figure { margin: 0; display: flex; flex-direction: column; height: 100%; }

.hypno--night { width: 100%; max-width: 12rem; height: auto; margin-bottom: 1.5rem; }

.reviews blockquote { margin: 0 0 1.5rem; flex: 1; }
.reviews blockquote p {
  margin: 0;
  font-size: 1.1875rem;
  line-height: 1.55;
  max-width: 34ch;
  text-wrap: pretty;
}

.reviews figcaption { display: flex; flex-wrap: wrap; gap: 0.25rem 0.75rem; }
.who { font-weight: 600; }
.where { color: var(--muted); }

/* ---------- Footer ---------- */
.footer { padding: 0 var(--gutter) 3rem; }

.hypno--wake { width: 100%; height: 2.5rem; margin-bottom: 2.5rem; }

.footer__inner {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.5rem 2rem;
  color: var(--muted);
}
.footer__inner .wordmark { color: var(--ink); margin-right: auto; }
.footer__inner p { margin: 0; }

/* ---------- Motion preferences ---------- */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .hypno--horizon { animation: none; }
  .button { transition: background-color 150ms linear; }
  .button:active { transform: none; }
}

